local function normalize(value)
    local normalized = string.lower(tostring(value or "")):gsub("[^%w]", "")
    return normalized
end

local function contains(value, fragment)
    return string.find(value, fragment, 1, true) ~= nil
end

local function runtimePath(root, object)
    local pieces = {}
    local current = object

    while current do
        table.insert(pieces, 1, normalize(current.Name))

        if current == root then
            break
        end

        current = current.Parent
    end

    return table.concat(pieces, "/")
end

local function storedPathKey(path)
    local pieces = {}

    for piece in string.gmatch(tostring(path or ""), "[^%.]+") do
        table.insert(pieces, normalize(piece))
    end

    return table.concat(pieces, "/")
end

for _, family in pairs(Registry.Families) do
    family.PathRoles = {}

    for _, region in ipairs(family.DamageRegions) do
        family.PathRoles[storedPathKey(region.Path)] = "HITBOX"
    end

    for _, region in ipairs(family.Telegraphs) do
        family.PathRoles[storedPathKey(region.Path)] = "PRECAST"
    end

    for _, region in ipairs(family.SafeRegions) do
        family.PathRoles[storedPathKey(region.Path)] = "IGNORE"
    end
end

function Registry:GetFamily(name)
    return self.Families[normalize(name)]
end

function Registry:MatchFamily(object)
    local current = object

    for _ = 1, 10 do
        if not current then
            break
        end

        local family = self.Families[normalize(current.Name)]

        if family then
            return family, current
        end

        current = current.Parent
    end

    return nil, nil
end

function Registry:Classify(object)
    if not object then
        return nil, nil
    end

    local family, root = self:MatchFamily(object)

    if not family then
        return nil, nil
    end

    local pathRole = family.PathRoles[runtimePath(root, object)]

    if pathRole == "IGNORE" then
        return nil, family
    end

    if pathRole then
        return pathRole, family
    end

    if family.Mode == "SAFE_ONLY"
        or family.Mode == "CONTEXT_ONLY" then

        return nil, family
    end

    local name = normalize(object.Name)

    if contains(name, "safe")
        or contains(name, "shelter")
        or name == "primarypart"
        or name == "pivot"
        or name == "origin" then

        return nil, family
    end

    if contains(name, "precast")
        or contains(name, "warning")
        or contains(name, "telegraph")
        or contains(name, "indicator") then

        return "PRECAST", family
    end

    if contains(name, "hitbox")
        or contains(name, "hurtbox")
        or contains(name, "damage") then

        return "HITBOX", family
    end

    if object:IsA("Beam") then
        return "LASER", family
    end

    if not object:IsA("BasePart") then
        return nil, family
    end

    if family.Mode == "EXPLICIT_REGIONS" then
        return nil, family
    end

    if family.Mode == "BEAM" then
        return "LASER", family
    end

    local familyName = family.NormalizedName

    if contains(familyName, "shot")
        or contains(familyName, "orb")
        or contains(familyName, "missile")
        or contains(familyName, "rock")
        or contains(familyName, "bomb")
        or contains(familyName, "shuriken")
        or contains(familyName, "spike") then

        return "PROJECTILE", family
    end

    return "ATTACK", family
end

return Registry
